pub fn number(word: []const u8) i64 { return std.fmt.parseInt(i64, word, 10) catch unreachable; }
pub fn integer(word: []const u8) usize { return @intCast(number(word)); }
pub fn split(source: []const u8, separator: u8) Strings {
    var result: std.ArrayList([]const u8) = .empty;
    var iterator = std.mem.splitScalar(u8, source, separator);
    while (iterator.next()) |part| append([]const u8, &result, part);
    return result.items;
}
pub const Record = struct { line: usize, source: usize, target: usize };
    const link_lines = lines(try directory.readFileAlloc(io, "input/links.csv", allocator, .unlimited))[1..];
    const records = alloc(Record, link_lines.len);
    for (link_lines, records, 2..) |line, *record, i| {
        const fields = split(line, ',');
        record.* = .{ .line = i, .source = integer(fields[0]), .target = integer(fields[1]) };
    }
    index: [10000]?usize = [_]?usize{null} ** 10000,
        const n = self.input.pages.len;
        var hosts: std.ArrayList([]const u8) = .empty;
        for (self.input.pages, 0..) |page, i| {
            self.index[page.id] = i;
        const weights = zeroWeights(n);
        const reasons = [_][]const u8{ "unknown", "self", "duplicate" };
        for (self.input.records) |record| {
            const u = self.index[record.source];
            const v = self.index[record.target];
            const reason: ?usize = if (u == null or v == null) 0 else if (u.? == v.?) 1 else if (weights[u.? * n + v.?] > 0) 2 else null;
            if (reason) |r| {
                self.ignored_counts[r] += 1;
                self.ignored.add("ignored line {d} {d},{d} {s}", .{ record.line, record.source, record.target, reasons[r] });
            } else weights[u.? * n + v.?] = 1;
        }
fn zeroWeights(count: usize) []usize { const result = D.alloc(usize, count * count); @memset(result, 0); return result; }
